fn has_common_minimal_class_xy(qord:&Vec<Vec<usize>>, min_elems_repr:&HashSet<usize>, x: usize, y: usize) -> bool {
    for t in min_elems_repr {
        if qord[*t][x] == 1 && qord[*t][y] == 1 {
            return true;
        }
    }
    false
}


